package com.cpf.batch.agent.internal; import com.cpf.batch.agent.AgentProperties; import com.cpf.batch.api.AgentArtifactRequest; import java.io.*; import java.net.*; import java.net.http.*; import java.nio.file.*; import java.time.Duration; import java.util.Objects; import java.util.regex.Pattern;
public final class ArtifactInstaller { private static final Pattern V=Pattern.compile("[A-Za-z0-9._-]{1,80}");private final AgentProperties p;private final ArtifactVerifier verifier;public ArtifactInstaller(AgentProperties p,ArtifactVerifier v){this.p=p;verifier=v;} public Result install(AgentArtifactRequest r)throws Exception{var s=service(r.serviceId());if(!r.coordinate().endsWith(":"+s.getArtifactId()))throw new SecurityException("artifact/service mismatch");if(!V.matcher(r.version()).matches())throw new SecurityException("unsafe version");Path root=Path.of(s.getInstallRoot()).toAbsolutePath().normalize(),dir=root.resolve("releases").resolve(r.version()).normalize();inside(root,dir);Files.createDirectories(dir);String ext="external-tomcat-war".equalsIgnoreCase(r.runtimeMode())?".war":".jar";Path target=dir.resolve(s.getArtifactId()+ext),tmp=dir.resolve(s.getArtifactId()+ext+".part");URI u=uri(r.coordinate(),r.version(),ext);HttpResponse<InputStream> resp=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NORMAL).build().send(HttpRequest.newBuilder(u).timeout(Duration.ofMinutes(5)).GET().build(),HttpResponse.BodyHandlers.ofInputStream());if(resp.statusCode()!=200)throw new IOException("repository status="+resp.statusCode());try(InputStream in=resp.body()){Files.copy(in,tmp,StandardCopyOption.REPLACE_EXISTING);}if(Files.size(tmp)>p.getMaxArtifactBytes())throw new SecurityException("artifact too large");verifier.verify(tmp,r.sha256(),r.signatureBase64());Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);
  if(r.configRef()!=null&&!r.configRef().isBlank()){
   if(!r.configRef().matches("(?i)^(vault|secret|config)://[A-Za-z0-9._/@:-]+$"))throw new SecurityException("Only approved secret/config references are allowed");
   Path cfg=root.resolve("config").resolve("deployment-config.ref").normalize();inside(root,cfg);Files.createDirectories(cfg.getParent());Files.writeString(cfg,r.configRef(),java.nio.charset.StandardCharsets.UTF_8);
  }Path current=root.resolve("current.version");String previous=Files.exists(current)?Files.readString(current).trim():"";if(!previous.isBlank())Files.writeString(root.resolve("previous.version"),previous);Files.writeString(current,r.version());return new Result(r.version(),previous,target.toString());} public String rollback(String id)throws Exception{var s=service(id);Path root=Path.of(s.getInstallRoot()).toAbsolutePath().normalize(),prev=root.resolve("previous.version");if(!Files.isRegularFile(prev))throw new IllegalStateException("no rollback version");String v=Files.readString(prev).trim();if(!V.matcher(v).matches())throw new SecurityException("invalid rollback version");if(!Files.isDirectory(root.resolve("releases").resolve(v)))throw new IllegalStateException("rollback release missing");String cur=Files.readString(root.resolve("current.version")).trim();Files.writeString(root.resolve("current.version"),v);Files.writeString(prev,cur);return v;} private URI uri(String c,String v,String ext){String[] a=c.split(":");if(a.length!=2)throw new IllegalArgumentException("coordinate");URI base=URI.create(p.getArtifactRepositoryBaseUrl()),u=URI.create(p.getArtifactRepositoryBaseUrl().replaceAll("/+$","")+"/"+a[0].replace('.','/')+"/"+a[1]+"/"+v+"/"+a[1]+"-"+v+ext);if(!Objects.equals(base.getHost(),u.getHost())||!Objects.equals(base.getScheme(),u.getScheme()))throw new SecurityException("repository escape");return u;} private AgentProperties.ServiceDefinition service(String id){return p.getServices().values().stream().filter(x->id.equals(x.getServiceId())).findFirst().orElseThrow(()->new SecurityException("service not approved"));}private static void inside(Path r,Path t){if(!t.startsWith(r))throw new SecurityException("path escape");}public record Result(String version,String previousVersion,String artifactPath){} }
